#!/usr/bin/env node
// Generated by meldr — wire-compatible API replacements without the rebuild.
//
// This server already behaves like your API contract out of the box.
// Take ownership route by route: fill in a handler below to override it,
// or delete the HANDLERS entry entirely to keep the faithful fallback.
//
// Run:            node server.mjs [--port N] [--host H] [--cors]
// Introspection:  /__meldr/routes   /__meldr/contract   /__meldr/health
// Tip:            curl -H "X-Meldr-Status: <code>" <url> forces any declared response.
//
// Regenerating with meldr gen --force overwrites edits — keep this file in git.

import http from 'node:http'

const SPEC = __MELDR_CONTRACT__

const HANDLERS = {
__MELDR_HANDLERS__
}

const FORMATS = {
  'date-time': '2024-01-15T10:30:00Z',
  date: '2024-01-15',
  time: '10:30:00Z',
  uuid: '123e4567-e89b-12d3-a456-426614174000',
  email: 'user@example.com',
  uri: 'https://example.com/resource',
  url: 'https://example.com/resource',
  hostname: 'example.com',
  ipv4: '127.0.0.1',
  ipv6: '::1',
  byte: 'bWVsZHI=',
  password: 'meldr-secret-1',
}

const NAMES = {
  id: 'id_1',
  name: 'meldr-demo',
  title: 'Meldr Demo',
  description: 'A wonderful resource.',
  message: 'ok',
  code: 'OK',
  status: 'active',
  city: 'San Francisco',
  country: 'US',
  currency: 'USD',
  phone: '+15551234567',
  address: '123 Market St',
  tag: 'core',
  tags: 'core',
  category: 'general',
  token: 'c15e6b9a2f8d47c0b3a19e7d5c4f2861',
  slug: 'meldr-demo',
  kind: 'standard',
  label: 'core',
}

const MAX_DEPTH = 6

function synth(schema, propName, dir, depth = 0) {
  if (!schema || schema.type === 'any') return null
  if (schema.type === 'never') return undefined
  if (depth >= MAX_DEPTH) return leaf(schema, propName)
  if (schema.example !== undefined) return clone(schema.example)
  if (Array.isArray(schema.examples) && schema.examples.length) return clone(schema.examples[0])
  if (schema.default !== undefined) return clone(schema.default)
  if (Array.isArray(schema.enum) && schema.enum.length) return clone(schema.enum[0])
  if (schema.const !== undefined) return clone(schema.const)
  if (FORMATS[schema.format] !== undefined) return FORMATS[schema.format]
  if (schema.type === 'object') return synthObject(schema, dir, depth)
  if (schema.type === 'array') return synthArray(schema, propName, dir, depth)
  return leaf(schema, propName)
}

function synthObject(schema, dir, depth) {
  const obj = {}
  for (const prop of Object.values(schema.properties ?? {})) {
    if (dir === 'request' && prop.readOnly) continue
    if (dir === 'out' && prop.writeOnly) continue
    obj[prop.name] = synth(prop.schema, prop.name, dir, depth + 1)
  }
  return obj
}

function synthArray(schema, propName, dir, depth) {
  let n = Math.max(schema.minItems ?? -1, 2)
  n = Math.min(n, 3)
  if ((schema.maxItems ?? -1) >= 0) n = Math.min(n, schema.maxItems)
  if (n < 0 || !schema.items) return []
  return Array.from({ length: n }, () => synth(schema.items, propName, dir, depth + 1))
}

function leaf(schema, propName) {
  const nm = String(propName ?? '').toLowerCase()
  switch (schema.type) {
    case 'string':
      return NAMES[nm] ?? 'meldr'
    case 'integer': {
      const lo = schema.minimum ?? 1
      const hi = schema.maximum
      return Math.trunc(hi !== null && lo > hi ? hi : lo)
    }
    case 'number': {
      const lo = schema.minimum ?? 1.25
      const hi = schema.maximum
      return hi !== null && lo > hi ? hi : lo
    }
    case 'boolean':
      return true
    default:
      return NAMES[nm] ?? null
  }
}

function clone(v) {
  try {
    return structuredClone(v)
  } catch {
    return JSON.parse(JSON.stringify(v ?? null))
  }
}

function selectMedia(content, acceptHeader) {
  const entries = Object.values(content ?? {})
  if (!entries.length) return null
  const accepts = String(acceptHeader ?? '')
    .split(',')
    .map((s) => s.split(';')[0].trim().toLowerCase())
    .filter(Boolean)
  for (const a of accepts) {
    const exact = entries.find((m) => m.mediaType === a)
    if (exact) return exact
  }
  for (const a of accepts) {
    if (a.endsWith('/*')) {
      const prefix = a.slice(0, a.indexOf('/') + 1)
      const partial = entries.find((m) => m.mediaType.startsWith(prefix))
      if (partial) return partial
    }
  }
  return entries.find((m) => m.mediaType.includes('json')) ?? entries[0]
}

function mediaExample(media) {
  if (!media) return undefined
  if (media.example !== undefined) return clone(media.example)
  const keys = media.examples ? Object.keys(media.examples) : []
  if (keys.length) return clone(media.examples[keys[0]])
  return undefined
}

function pickSuccess(op) {
  const codes = Object.keys(op.responses).filter((k) => /^2\d\d$/.test(k)).sort()
  if (codes.length) return op.responses[codes.includes('200') ? '200' : codes[0]]
  return op.responses['2XX'] ?? op.responses.default ?? null
}

function lookupResponse(op, status) {
  const k = String(status)
  return op.responses[k] ?? op.responses[k[0] + 'XX'] ?? op.responses.default ?? null
}

function declaredKeys(op) {
  return Object.keys(op.responses).sort()
}

function splitPath(p) {
  return p.split('/').filter((s) => s.length > 0)
}

function matchSegments(template, actual) {
  if (template.length !== actual.length) return null
  const vars = {}
  for (let i = 0; i < template.length; i++) {
    const t = template[i]
    if (t.startsWith('{') && t.endsWith('}')) {
      try {
        vars[t.slice(1, -1)] = decodeURIComponent(actual[i])
      } catch {
        vars[t.slice(1, -1)] = actual[i]
      }
    } else if (t !== actual[i]) {
      return null
    }
  }
  return vars
}

function decodeSafe(s) {
  try {
    return decodeURI(s)
  } catch {
    return s
  }
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let size = 0
    req.on('data', (chunk) => {
      size += chunk.length
      if (size > 2 * 1024 * 1024) {
        reject(new Error('body_too_large'))
        req.destroy()
        return
      }
      chunks.push(chunk)
    })
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    req.on('error', reject)
  })
}

function applyCors(res) {
  res.setHeader('access-control-allow-origin', '*')
  res.setHeader('access-control-allow-methods', 'GET, POST, PUT, PATCH, DELETE, OPTIONS')
  res.setHeader('access-control-allow-headers', 'content-type, accept, x-meldr-status, authorization')
  res.setHeader('access-control-max-age', '600')
}

async function handle(req, res) {
  let url
  try {
    url = new URL(req.url, 'http://meldr.local')
  } catch {
    return send(res, 400, { error: 'bad_request' })
  }

  if (url.pathname === '/__meldr/routes') return send(res, 200, { api: SPEC.title, version: SPEC.version, routes: SPEC.routes.map((r) => ({ method: r.method.toUpperCase(), path: r.fullPath, id: r.id })) })
  if (url.pathname === '/__meldr/health') return send(res, 200, { status: 'ok', api: SPEC.title, version: SPEC.version })
  if (url.pathname === '/__meldr/contract') {
    res.writeHead(200, { 'content-type': 'application/json; charset=utf-8' })
    return res.end(JSON.stringify(SPEC.contract))
  }

  if (CORS && req.method === 'OPTIONS') {
    applyCors(res)
    res.writeHead(204)
    return res.end()
  }

  const target = splitPath(decodeSafe(url.pathname))
  let allowed = null
  let matched = null
  for (const route of SPEC.routes) {
    const vars = matchSegments(route.segments, target)
    if (vars === null) continue
    if (route.method === req.method.toLowerCase()) {
      matched = { route, vars }
      break
    }
    allowed = allowed ?? new Set(['OPTIONS'])
    allowed.add(route.method.toUpperCase())
  }

  if (!matched && !allowed) return send(res, 404, { error: 'not_found', message: `no route matches ${req.method} ${url.pathname}` })
  if (!matched) {
    res.setHeader('allow', [...allowed].sort().join(', '))
    return send(res, 405, { error: 'method_not_allowed' })
  }

  const op = matched.route
  const violations = []
  for (const p of op.params) {
    if (!p.required) continue
    if (p.in === 'query' && !url.searchParams.has(p.name)) violations.push({ in: 'query', name: p.name, reason: 'required' })
    if (p.in === 'header' && !(p.name.toLowerCase() in req.headers)) violations.push({ in: 'header', name: p.name, reason: 'required' })
  }

  let rawBody = ''
  if (op.body) {
    rawBody = await readBody(req)
    const hasJson = Object.values(op.body.content).some((m) => m.mediaType.includes('json'))
    if (op.body.required && rawBody.trim() === '') violations.push({ in: 'body', name: 'requestBody', reason: 'required' })
    else if (rawBody.trim() !== '' && hasJson) {
      try {
        JSON.parse(rawBody)
      } catch {
        violations.push({ in: 'body', name: 'requestBody', reason: 'invalid_json' })
      }
    }
  }
  if (violations.length) return send(res, 400, { error: 'validation_failed', violations })

  let parsedBody = null
  if (rawBody.trim() !== '') {
    try {
      parsedBody = JSON.parse(rawBody)
    } catch {
      parsedBody = rawBody
    }
  }

  const ctx = {
    params: matched.vars,
    query: Object.fromEntries(url.searchParams),
    headers: req.headers,
    body: parsedBody,
    request: req,
  }

  const key = `${op.method.toUpperCase()} ${op.fullPath}`
  const handler = HANDLERS[key]
  let custom = null
  if (typeof handler === 'function') {
    try {
      custom = await handler(ctx)
    } catch (e) {
      return send(res, 500, { error: 'handler_error', message: String(e && e.message ? e.message : e) })
    }
  }

  if (custom !== undefined && custom !== null) {
    const status = Number.isInteger(custom.status) ? custom.status : 200
    const headers = { ...(custom.headers ?? {}) }
    let text = ''
    if (custom.body !== undefined && custom.body !== null) text = typeof custom.body === 'string' ? custom.body : JSON.stringify(custom.body)
    if (!Object.keys(headers).some((h) => h.toLowerCase() === 'content-type') && typeof custom.body !== 'string') headers['content-type'] = 'application/json; charset=utf-8'
    if (CORS) applyCors(res)
    res.writeHead(status, headers)
    return res.end(text)
  }

  let response = null
  let status
  const forced = req.headers['x-meldr-status']
  if (forced !== undefined) {
    const forcedStatus = Number.parseInt(String(forced), 10)
    response = Number.isInteger(forcedStatus) ? lookupResponse(op, forcedStatus) : null
    if (!response) {
      return send(res, 400, { error: 'unknown_status', message: `X-Meldr-Status ${forced} is not declared for ${key}`, declared: declaredKeys(op) })
    }
    status = forcedStatus
  } else {
    response = pickSuccess(op)
    if (!response) return send(res, 200, {})
    status = /^\d{3}$/.test(response.key) ? Number(response.key) : 200
  }

  const media = selectMedia(response.content, req.headers.accept)
  const headers = {}
  if (media) headers['content-type'] = media.mediaType.includes('json') ? `${media.mediaType}; charset=utf-8` : media.mediaType

  for (const [name, h] of Object.entries(response.headers ?? {})) {
    const v = synth(h.schema, name.toLowerCase(), 'out')
    if (v !== undefined && v !== null) headers[name.toLowerCase()] = String(v)
  }

  let text = ''
  if (media) {
    const example = mediaExample(media)
    text = JSON.stringify(example !== undefined ? example : synth(media.schema, '', 'out'))
  }

  if (CORS) applyCors(res)
  res.writeHead(status, headers)
  res.end(text)
}

function send(res, status, obj) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' })
  res.end(JSON.stringify(obj))
}

const args = process.argv.slice(2)
let PORT = Number(process.env.PORT ?? 3000)
let HOST = '127.0.0.1'
for (let i = 0; i < args.length; i++) {
  const a = args[i]
  if (a === '--port') PORT = Number(args[++i])
  else if (a.startsWith('--port=')) PORT = Number(a.slice('--port='.length))
  else if (a === '--host') HOST = args[++i]
  else if (a.startsWith('--host=')) HOST = a.slice('--host='.length)
}
const CORS = args.includes('--cors')

if (!Number.isInteger(PORT) || PORT < 0 || PORT > 65535) {
  console.error(`meldr: invalid port ${PORT}`)
  process.exit(1)
}

const server = http.createServer((req, res) => {
  const startedAt = Date.now()
  res.on('finish', () => {
    console.error(`[meldr] ${req.method} ${req.url} ${res.statusCode} ${Date.now() - startedAt}ms`)
  })
  Promise.resolve(handle(req, res)).catch((e) => {
    if (!res.headersSent) send(res, 500, { error: 'internal_error', message: String(e && e.message ? e.message : e) })
  })
})

server.listen(PORT, HOST, () => {
  console.error(`  meldr serving "${SPEC.title}" v${SPEC.version}`)
  console.error(`  -> http://${HOST}:${PORT}${SPEC.basePath === '/' ? '' : SPEC.basePath}`)
  console.error(`  introspection: /__meldr/routes - /__meldr/contract - /__meldr/health`)
  console.error(`  ^C to stop`)
})

process.on('SIGINT', () => {
  server.close(() => process.exit(0))
  setTimeout(() => process.exit(0), 500).unref()
})
